&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Extensive experience in cost engineering, product costing, value engineering, industrial engineering, operational excellence, or cost optimization &lt;strong&gt;within automotive/aviation/ship building, lean manufacturing, high-volume production&lt;/strong&gt;, or similarly advanced industrial environments&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:0,&amp;quot;335551620&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:300}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
